mapper.select:
SELECT e.EMPLOYEE_ID AS id, e.EMPLOYEE_NAME AS name, d.DEPARTMENT_NAME AS departmentName, e.SALARY AS salary FROM EMPLOYEE e JOIN DEPARTMENT d ON d.DEPARTMENT_ID = e.DEPARTMENT_ID
AND e.DEPARTMENT_ID = #{departmentId} AND e.SALARY >= #{minimumSalary}
AND e.EMPLOYEE_ID IN #{id}
ORDER BY e.EMPLOYEE_ID
